"""Brand, record-label and archival pages, driven by the public content collections."""
import json,re,datetime

def build_archive_pages(g):
    OUT=g['OUT'];shell=g['shell'];image=g['image'];esc=g['esc'];intro=g['intro'];card=g['card'];SITE=g['SITE']
    def data(name):return json.loads((OUT/'content'/name).read_text())
    events=sorted(data('events.json'),key=lambda e:e.get('date') or '',reverse=True)
    stories=data('archive-stories.json');features=data('featured-releases.json');releases=data('releases.json');current=data('current-releases.json')
    def img(name,alt,eager=False):return image('/assets/archive/'+name+'.webp',alt,eager=eager)
    def releasecard(r):
        return f'<a class="sleeve-card" href="/record-label/releases/{r["id"]}/"><div class="sleeve-art">{image(r["image"],r["title"]+" — original "+r["artist"]+" artwork")}<span class="sleeve-arrow" aria-hidden="true">↗</span></div><span class="eyebrow">{esc(r["edition"])}</span><h3>{esc(r["title"])}</h3><p>{esc(r["artist"])}</p></a>'
    recent=events[:6]
    recent_slides=''
    for i,e in enumerate(recent):
        recent_slides+=f'<article class="show-slide"{(" hidden" if i else "")}><a class="show-slide-poster" href="/events/{e["slug"]}/">{image(e["image"],e["title"]+" original event flyer",eager=i==0)}</a><div class="show-slide-copy"><p class="eyebrow">RECENT HISTORY / {esc(e["display"])}</p><h2>{esc(e["title"])}</h2><p class="show-venue">{esc(e["venue"])}<br>{esc(e["city"])}</p><p>{esc(e["description"])}</p><a class="button gold" href="/events/{e["slug"]}/">Explore the show ↗</a></div></article>'
    recent_feature='<section class="section recent-shows" aria-label="Featured recent shows" aria-roledescription="carousel"><div class="section-heading"><div><p class="eyebrow">THE SHOWS / THE PEOPLE / THE HISTORY</p><h2>Relive the<br><em>experience.</em></h2></div><div class="show-controls"><button data-show-prev aria-label="Previous featured show">←</button><button data-show-pause aria-pressed="false">Pause slideshow</button><button data-show-next aria-label="Next featured show">→</button></div></div><div class="show-hero-track"><button class="show-preview show-preview-prev" aria-label="Show previous flyer">'+image(recent[-1]['image'],'')+'<span>Previous show</span></button><div class="show-stage">'+recent_slides+'</div><button class="show-preview show-preview-next" aria-label="Show next flyer">'+image(recent[1]['image'],'')+'<span>Next show</span></button></div><a class="text-link" href="/studio/#history">Explore the full event archive ↗</a></section>'
    brandhero=f'''<section class="brand-hero"><div class="brand-hero-copy"><p class="eyebrow">RECORDS · LIVE EVENTS · REGGAE CULTURE</p><h1>KINGS<br>OF KINGS<span>INTERNATIONAL</span></h1><p class="brand-intro">The music. The people.<br>A history worth discovering.</p><div class="hero-actions"><a class="button gold" href="/studio/#upcoming">Explore events ↗</a><a class="text-link" href="/record-label/">Enter Kings of Kings Records →</a></div><div class="brand-signature">ROOTS. CULTURE. TRUTH. LOVE.</div></div><div class="brand-archive-wall">{img('shows-display','Original Kings of Kings concert flyers featuring artists from the event archive',True)}<div class="wall-caption"><span>THE KINGS ARCHIVE</span><a href="/history/">Discover the stories ↗</a></div></div></section>'''
    brandhero=f'''<section class="brand-hero rasta-hero"><div class="rasta-art" aria-hidden="true"><div class="rasta-poster rasta-one">{img('miracle','',True)}</div><div class="rasta-poster rasta-two">{image('/assets/live-archive/live-48.webp','',eager=True)}</div><div class="rasta-poster rasta-three">{img('cocoa-tea-2018','',True)}</div><div class="rasta-poster rasta-four">{image('/assets/live-archive/live-61.webp','',eager=True)}</div></div><div class="brand-hero-copy"><p class="eyebrow">ROOTS. CULTURE. TRUTH. LOVE.</p><h1>KINGS OF KINGS<span>INTERNATIONAL</span></h1><p class="brand-intro">Legendary Voices,<br>Unforgettable Experiences!</p><p class="brand-hero-note">From the record to the stage.<br>Discover the people and music behind the Kings legacy.</p><div class="hero-actions"><a class="button gold" href="/studio/">Explore the shows ↗</a><a class="text-link" href="/record-label/">Kings of Kings Records →</a></div></div><a class="rasta-caption" href="/history/">REAL ARTISTS. ORIGINAL ARTWORK. OUR SHARED HISTORY. ↗</a></section>'''
    home=brandhero+'''<div class="brand-paths"><a href="/studio/#upcoming"><span>WHAT’S NEXT</span><strong>Upcoming events</strong><b aria-hidden="true">↗</b></a><a href="/studio/#history"><span>LIVE HISTORY</span><strong>The shows we remember</strong><b aria-hidden="true">↗</b></a><a href="/record-label/"><span>THE LABEL</span><strong>Kings of Kings Records</strong><b aria-hidden="true">↗</b></a></div>'''
    showcase=f'''<section class="section current-releases" aria-label="Current releases"><div class="section-heading"><div><p class="eyebrow">KINGS OF KINGS RECORDS / RIGHT NOW</p><h2>The latest sound.<br><em>Always moving.</em></h2></div><div class="release-controls"><button class="release-prev" aria-label="Previous releases">←</button><button class="release-pause" aria-pressed="false">Pause motion</button><button class="release-next" aria-label="Next releases">→</button></div></div><div class="release-flow" tabindex="0" aria-label="Current releases — swipe or use arrow controls">{''.join(releasecard(r) for r in current)}</div><div class="release-footer"><p>Current releases from Kings of Kings. Swipe to explore.</p><a class="text-link" href="/record-label/">Explore Kings of Kings Records ↗</a></div></section>'''
    album=f'''<section class="section album-spotlight" id="upliftment"><a class="album-cover" href="/record-label/releases/upliftment/">{image('/assets/current/upliftment.webp','Upliftment — Iley Dread original album cover',eager=True)}</a><div><p class="eyebrow">ILEY DREAD / THE NEW ALBUM</p><h2>Upliftment.</h2><p class="album-lead">A new chapter.<br>A higher vibration.</p><div class="album-dates"><p><span>ALBUM STREET DATE</span><strong><time datetime="2027-01-05">January 5, 2027</time></strong></p><p><span>EARLY RELEASE / ITUNES STORE</span><strong><time datetime="2026-11-27">November 27, 2026</time></strong></p></div><p>Early release copies available at the iTunes Store starting November 27, 2026.</p><a class="button gold" href="/record-label/releases/upliftment/">Discover the album ↗</a></div></section>'''
    home+=album+showcase


    home+=f'''<section class="section heritage-feature"><a class="heritage-poster" href="/history/#capleton-cocoa-tea">{img('capleton-archive','Original Capleton Reign of Fire Tour flyer with special guest Cocoa Tea at B.B. King Blues Club')}</a><div><p class="eyebrow">THE ARTISTS. THE MEMORIES. THE CONNECTIONS.</p><h2>A stage for<br><em>reggae’s greats.</em></h2><p>From Capleton and Cocoa Tea to Judy Mowatt and Iley Chardavid, the archive tells its story through original show flyers, record sleeves and release campaigns.</p><p>Explore the people behind the music, and the moments that brought audiences together.</p><a class="button outline" href="/history/">Step into the Kings archive ↗</a></div></section>'''
    brand_small=f'''<section class="section brand-marks"><div class="section-heading"><div><p class="eyebrow">THE KINGS SIGNATURE / ON RECORD</p><h2>A name.<br><em>Many impressions.</em></h2></div><a class="text-link" href="/history/brand-identity/#record-label-marks">Discover the marks & their dates ↗</a></div><div class="brand-mark-grid"><a href="/history/brand-identity/#record-label-marks"><div>{image('/assets/identity/records/brand-1.webp','Original Kings of Kings star and wordmark from Discogs label artwork')}</div><h3>The star & wordmark</h3><p>Seen on releases dated 1995–96.</p></a><a href="/history/brand-identity/#record-label-marks"><div>{image('/assets/identity/records/brand-0.webp','Original Kings of Kings crown recording label mark from Discogs')}</div><h3>The crown signature</h3><p>Documented on a release dated 1997, with later variants.</p></a><a href="/history/brand-identity/#record-label-marks"><div>{image('/assets/identity/records/brand-2.webp','Original King of Kings International mark preserved on Discogs')}</div><h3>The International mark</h3><p>Preserved in the label image gallery. Date unconfirmed.</p></a></div></section>'''
    home+=brand_small
    home+=recent_feature

    home+='''<section class="section pathways"><p class="eyebrow">MAKE YOUR CONNECTION</p><a href="/contact/#bookings"><span>LIVE EVENTS</span><h2>Bring the experience.</h2><span aria-hidden="true">↗</span></a><a href="/contact/#artists"><span>ARTISTS & RECORDINGS</span><h2>Share your sound.</h2><span aria-hidden="true">↗</span></a><a href="/contact/#partners"><span>PARTNERSHIPS</span><h2>Build something together.</h2><span aria-hidden="true">↗</span></a></section>'''
    shell('/','Kings of Kings International | Records, Reggae & Live Events','Discover Kings of Kings International: reggae records, original artwork, artist release credits and a visual history of live concerts and showcases.',home)
    # Public catalogue uses selected metadata only. Private legal/review columns are never copied.
    artists=sorted(set(r['artist'].split(' / ')[0] for r in releases))
    catalogue=''
    for r in releases:
        art=image(r['image'],r['title']+' record label artwork') if r.get('image') else '<span class="record-mark" aria-hidden="true">◎</span>'
        catalogue+=f'''<article class="catalogue-card" data-catalogue-item data-search="{esc((r['artist']+' '+r['title']+' '+r['year']).lower())}" data-artist="{esc(r['artist'].split(' / ')[0])}"><div class="catalogue-art">{art}</div><div><span class="catalogue-year">{esc(r['year'] or 'ARCHIVE')}</span><h3>{esc(r['title'])}</h3><p>{esc(r['artist'])}</p><p class="catalogue-format">{esc(r['label'])} · {esc(r['format'])}</p><a href="{esc(r['source_url'])}" target="_blank" rel="noopener noreferrer">View release reference ↗</a></div></article>'''
    label=f'''<section class="record-hero"><div><p class="eyebrow">THE RECORD LABEL</p><h1>KINGS OF<br>KINGS <em>RECORDS</em></h1><p>Roots in the music.<br>Stories in every groove.</p><div class="hero-actions"><a class="button gold" href="#discography">Explore the discography ↓</a><a class="text-link" href="#catalogue">Browse release credits →</a></div></div><div class="record-hero-art"><div class="vinyl-disc" aria-hidden="true"></div>{img('unite-the-people','Unite the People — digitally remastered artwork, Colin Levy aka Iley Dread',True)}</div></section>'''
    label+=album+showcase
    label+=f'''<section class="section" id="discography"><div class="section-heading"><div><p class="eyebrow">THE MUSIC / SELECTED RELEASE ARTWORK</p><h2>Put a face<br><em>to the sound.</em></h2></div><p class="section-description">Original covers and campaign artwork from the Kings archive. Open a release to discover its story.</p></div><div class="sleeve-grid">{''.join(releasecard(r) for r in features)}</div></section>'''
    label+=f'''<section class="section label-story"><div>{img('unleashed-portrait','Original Colin Levy aka Iley Dread Unleashed campaign artwork')}</div><div><p class="eyebrow">ONE ARTIST. MORE THAN ONE CHAPTER.</p><h2>Colin Levy.<br>Iley Dread.<br><em>Iley Chardavid.</em></h2><p>The original covers trace the names used across the recording campaigns: Colin Levy aka Iley Dread on <em>Unite the People</em>, Colin Levy on <em>Lover’s Holiday</em>, and Iley Chardavid on <em>Unleashed</em>.</p><p>The archive connects those recordings with the concert stage through the Montréal and Toronto showcase flyers.</p><a class="text-link" href="/artists/colin-levy/">Explore the artist’s archive ↗</a><br><a class="text-link" href="/artists/">More artists in the Kings archive →</a></div></section>'''
    label+=f'''<section class="section" id="catalogue"><div class="section-heading"><div><p class="eyebrow">DIG INTO THE RELEASES</p><h2>The catalogue.<br><em>Beyond the sleeve.</em></h2></div><p class="section-description">Browse documented Kings label credits. A release credit records a connection to that release; it does not imply an exclusive artist contract.</p></div><div class="catalogue-controls"><label>Search artist, title or year<input type="search" id="catalogue-search" placeholder="Try Beenie Man, Capleton or 2003…"></label><label>Artist<select id="catalogue-artist"><option value="">All artists</option>{''.join('<option>'+esc(a)+'</option>' for a in artists)}</select></label><p id="catalogue-count" role="status">{len(releases)} releases</p></div><div class="catalogue-grid">{catalogue}</div><p id="catalogue-empty" hidden>No matching releases. Try another title or artist.</p><p class="small-note">Release references are drawn from the supplied catalogue’s retrieved Discogs metadata. This is a selected discography, not a statement of current rights ownership or the complete label catalogue.</p></section>'''
    shell('/record-label/','Kings of Kings Records | Reggae Label & Discography','Explore Kings of Kings Records: original releases, Colin Levy and Iley Dread artwork, reggae and dancehall label credits, and the stories behind the catalogue.',label,{'@context':'https://schema.org','@type':'CollectionPage','name':'Kings of Kings Records discography','url':SITE+'/record-label/','about':{'@type':'Organization','name':'Kings of Kings Records'}})
    shell('/record-label/releases/upliftment/','Upliftment — Iley Dread | New Album January 5, 2027','Upliftment, the new Iley Dread album. Street date January 5, 2027; early release copies at the iTunes Store starting November 27, 2026.',intro('KINGS OF KINGS RECORDS / NEW ALBUM','Upliftment.','Iley Dread')+album,{'@context':'https://schema.org','@type':'MusicAlbum','name':'Upliftment','byArtist':{'@type':'MusicGroup','name':'Iley Dread'},'image':SITE+'/assets/current/upliftment.webp','description':'Album street date January 5, 2027. Early release copies available at the iTunes Store starting November 27, 2026.'})
    for r in features+current:
        body=intro('KINGS OF KINGS RECORDS / THE RELEASE ARCHIVE',esc(r['title']),esc(r['artist']))+f'''<section class="section release-detail"><div>{image(r['image'],r['title']+' original artwork')}</div><div><span class="label">{esc(r['edition'])}</span><h2>The story<br><em>on the sleeve.</em></h2><p>{esc(r['description'])}</p><p>Explore the original artwork in full, alongside the other recordings from Kings of Kings.</p><a class="button gold" href="/record-label/#discography">Back to the discography ↗</a><p class="small-note">Release dates, track lists and listening links will be added when verified.</p></div></section>'''
        shell('/record-label/releases/'+r['id']+'/',r['title']+' — '+r['artist'],r['description'],body,{'@context':'https://schema.org','@type':'CreativeWork','name':r['title'],**({'creator':{'@type':'MusicGroup','name':r['artist']}} if r['artist'] else {}),'image':SITE+r['image']})
    history=intro('ORIGINAL ARTWORK / ORIGINAL CONNECTIONS','The Kings<br><em>archive.</em>','Follow the records, the artists and the shows through original artwork. Each story is grounded in an original flyer, cover or release reference.')
    for i,s in enumerate(stories):
        history+=f'''<section class="section archive-story" id="{s['id']}"><div class="archive-story-image">{image(s['image'],s['title']+' original archive artwork')}</div><div><p class="eyebrow">{esc(s['kicker'])}</p><h2>{esc(s['title'])}</h2><p>{esc(s['text'])}</p><p class="archive-caption">{esc(s['caption'])}</p><button class="button outline archive-enlarge" data-image="{s['image']}" data-alt="{esc(s['title'])} original artwork">View original artwork ↗</button></div></section>'''
    history+=f'<section class="section"><div class="section-heading"><div><p class="eyebrow">THE SHOWCASE YEARS</p><h2>Records come<br><em>to life.</em></h2></div></div><div class="event-grid">'+''.join(card(e) for e in events if e['slug'] in ['unleashed-toronto-2016','unleashed-montreal-2016','1000-degrees-2018'])+'</div></section>'
    history+='<section class="section"><p class="eyebrow">THE IDENTITY THROUGH THE ARCHIVE</p><h2>The crown.<br><em>The crest. The colours.</em></h2><p>Explore the original Kings of Kings logos and banners, from the crown wordmark to the International lions crest.</p><a class="button gold" href="/history/brand-identity/">Explore our visual history ↗</a></section>'
    shell('/history/','The Kings Archive | Reggae Artists, Shows & Stories','Discover original Kings artwork, Capleton and Cocoa Tea flyers, Colin Levy release showcases, reggae artists and historic concert posters.',history)
    posters=data('live-event-posters.json')
    posterbody=intro('CAPTURED FROM THE LIVE SITE','The original<br><em>event collection.</em>','Discover additional concert posters, partner events and regional campaigns retained from the Kings website. Unresolved dates stay identified as such.')
    for r in posters:
        poster_slug=re.sub(r'[^a-z0-9]+','-',r['title'].lower()).strip('-')
        poster_path='/history/posters/'+poster_slug+'/'
        shell(poster_path,r['title']+' | Original Event Poster',r['description'],intro('THE ORIGINAL EVENT ARCHIVE',esc(r['title']),r['description'])+f'<section class="section release-detail"><div>{image(r["image"],r["title"]+" original poster")}</div><div><h2>The original<br><em>announcement.</em></h2><p>{esc(r["description"])}</p><p>This archive preserves the advertised event. It does not assert attendance, final running order or an independently verified outcome.</p><a class="text-link" href="{esc(r["source_url"])}">Original website reference ↗</a><p><a class="button gold" href="/studio/#history">Back to event history ↗</a></p></div></section>')
        posterbody+=f'<section class="section archive-story"><div class="archive-story-image">{image(r["image"],r["title"]+" archived poster")}</div><div><h2><a href="{poster_path}">{esc(r["title"])}</a></h2><p>{esc(r["description"])}</p><a class="text-link" href="{poster_path}">Explore this event ↗</a><br><button class="button outline" data-image="{r["image"]}" data-alt="{esc(r["title"])}">Enlarge the poster ↗</button><p><a class="text-link" href="{esc(r["source_url"])}">Original site reference ↗</a></p></div></section>'
    posterbody+='<section class="section"><p class="eyebrow">PRESERVED CAMPAIGNS / ALTERNATE FLYERS</p><h2>Every flyer.<br><em>Its own story.</em></h2><p>Fronts, backs, early announcements and updated posters from the original site. Several images refer to the same event. Historical advertisements do not confirm that a show occurred or that Kings produced an externally promoted event.</p><div class="flyer-tile-grid">'
    flyer_rows=data('flyers.json')
    for r in flyer_rows:
        flyer_path='/history/flyers/'+r['id']+'/'
        stars=' · '.join(r['stars']) if r['stars'] else 'No specific performance lineup confirmed on this announcement.'
        details=f'<section class="section event-detail"><div class="detail-poster">{image(r["image"],r["title"]+" full original flyer")}</div><div class="detail-copy"><p class="eyebrow">THE ADVERTISED SHOW</p><h2>{esc(r["title"])}</h2><dl><dt>Date</dt><dd>{esc(r["date"])}</dd><dt>Venue</dt><dd>{esc(r["venue"])}</dd><dt>Location</dt><dd>{esc(r["location"])}</dd></dl><h3>Stars & advertised names</h3><p>{esc(stars)}</p><p>{esc(r["description"])}</p><p class="small-note">Original promotional material. Prices and offers are historical; names refer to the advertised programme. Date uncertainties are retained rather than inferred.</p>'
        if r['event_url']:details+=f'<a class="text-link" href="{r["event_url"]}">Explore the main event record ↗</a><br>'
        details+=f'<a class="text-link" href="{esc(r["source_url"])}">Original website source ↗</a><p><a class="button gold" href="/history/site-event-collection/">Back to all flyers ↗</a></p></div></section>'
        shell(flyer_path,r['title']+' — '+r['date'],r['title']+'. '+r['date']+'. '+r['location']+'. Original flyer and advertised performers.',intro('THE FLYER ARCHIVE',esc(r['title']),esc(r['date'])+' · '+esc(r['location']))+details)
        posterbody+=f'<a class="flyer-tile" href="{flyer_path}">{image(r["image"],r["title"]+" original flyer")}<span>{esc(r["title"])}</span><small>{esc(r["date"])}</small><b aria-hidden="true">↗</b></a>'
    posterbody+='</div></section>'
    posterbody+='<section class="section"><a class="button gold" href="/studio/#history">Back to dated event history ↗</a></section>'
    shell('/history/site-event-collection/','Original Event Posters & Campaigns | Kings Archive','Explore preserved Kings concert posters, regional campaigns and partner-event artwork, with clear dates and source references.',posterbody)
    identity=intro('THE VISUAL HISTORY','The crown.<br>The crest.<br><em>The Kings identity.</em>','A visual archive of the marks, banners and campaign artwork that have represented Kings of Kings. Original designs are preserved without redrawing the identity.')
    identity+=f'<section class="section identity-family"><div class="identity-logo ivory">{image("/assets/identity/logo-1126.webp","Original Kings of Kings red gold and green crown wordmark")}</div><div><p class="eyebrow">THE CROWN / ROOTS IN COLOUR</p><h2>A crown.<br><em>A cultural signature.</em></h2><p>The red, gold and green crown appears across the record artwork and concert campaigns in the archive. Its lettering and proportions vary across the original files.</p><p>The Toronto Unleashed showcase flyer explicitly dates one use of this mark to May 1, 2016. The record and campaign archive preserves other examples; the logo’s creation date is not established.</p><a class="text-link" href="/events/unleashed-toronto-2016/">See the 2016 showcase ↗</a></div></section>'
    identity+=f'<section class="section identity-family"><div class="identity-logo ivory">{image("/assets/identity/logo-1357.webp","Original Kings of Kings International crown and twin lions crest")}</div><div><p class="eyebrow">THE CREST / INTERNATIONAL</p><h2>The lions.<br><em>The international name.</em></h2><p>The crown, twin lions and central K form another family of Kings of Kings International marks. The live website preserves both a stacked crest and a horizontal header version.</p><p>The website’s media paths place these copies in 2023. That documents their presence in the site archive, rather than proving the year the identity was designed.</p></div></section>'
    identity+=f'<section class="section identity-variants"><p class="eyebrow">ORIGINAL VARIANTS / PRESERVED AS FOUND</p><h2>One name.<br><em>Different expressions.</em></h2><div class="identity-variant-grid"><figure class="identity-logo ivory">{image("/assets/identity/logo-1360.webp","Horizontal Kings of Kings crest and wordmark")}<figcaption>Horizontal website header mark · live-site archive</figcaption></figure><figure class="identity-logo ivory">{image("/assets/identity/logo-1343.webp","Black stacked Kings of Kings International crest")}<figcaption>Black crest variant · live-site archive</figcaption></figure><figure class="identity-logo">{image("/assets/archive/kings-international-logo.webp","Supplied gold Kings of Kings International crest on black")}<figcaption>Gold crest · supplied brand archive, undated</figcaption></figure><figure class="identity-logo ivory">{image("/assets/archive/kings-records-logo.webp","Supplied Kings of Kings rainbow crown wordmark")}<figcaption>Crown wordmark · supplied brand archive, undated</figcaption></figure></div></section>'
    identity+=f'<section class="section"><p class="eyebrow">BEYOND THE LOGO / THE BANNERS</p><h2>Colour carries<br><em>the culture.</em></h2><div class="identity-banner">{image("/assets/live-archive/live-10.webp","Original colourful Kings of Kings International site banner")}</div><p>The original live-site banner brings the crown together with red, gold and green, a concert audience and an illustrated reggae setting. It is preserved here as historical artwork.</p><div class="identity-variant-grid"><figure>{image("/assets/archive/shows-display.webp","Kings of Kings original concert-poster display banner")}<figcaption>Show-poster display · supplied archive</figcaption></figure><figure>{image("/assets/live-archive/live-21.webp","Kings of Kings illustrated lion and musician campaign banner")}<figcaption>Illustrated campaign artwork · live-site archive</figcaption></figure></div><p class="small-note">The banner illustrations are historical source artwork. They are not photographs of identified performers. The new homepage uses real artists pictured on original show and record artwork.</p><a class="button gold" href="/history/">Explore the music behind the marks ↗</a></section>'
    evidence=data('logo-release-evidence.json')
    identity+='<section class="section" id="record-label-marks"><p class="eyebrow">THE RECORD LABEL MARKS / DATED EVIDENCE</p><h2>Written into<br><em>the records.</em></h2><p>The scans below document how the label looked on particular releases. Years are the release years currently recorded by Discogs, not verified logo creation dates. A design may have been used earlier or on later repressings.</p><div class="brand-mark-grid">'
    for n,title,caption in [(1,'Star & wordmark','Matches the star-topped wordmark on records catalogued in 1995 and 1996.'),(0,'Crown recording label','A matching crown family is visible on Crime Stop, catalogued in 1997, and later releases.'),(2,'King of Kings International','Original label-gallery artwork. No dated matching pressing established in this sample.'),(3,'Crown / Recording Label variant','Original label-gallery variant. Its precise period remains unconfirmed.')]:
        identity+=f'<figure class="brand-mark-example"><div>{image("/assets/identity/records/brand-"+str(n)+".webp",title+" original Discogs label image")}</div><figcaption><h3>{title}</h3><p>{caption}</p><a class="text-link" href="https://www.discogs.com/label/39926-Kings-Of-Kings">Discogs label image reference ↗</a></figcaption></figure>'
    identity+='</div><h2 class="evidence-heading">The pressing evidence.</h2><div class="logo-evidence-grid">'
    for r in evidence:
        identity+=f'<article><a href="{esc(r["source_url"])}" target="_blank" rel="noopener noreferrer">{image(r["image"],r["title"]+" original record label scan")}<p class="eyebrow">{r["year"]} / DISCOGS RELEASE DATE</p><h3>{esc(r["title"])}</h3><p>{esc(r["artist"])}</p><p>{esc(r["style"])}</p><span class="text-link">Inspect the release reference ↗</span></a></article>'
    identity+='</div><p class="small-note">These are archival record photographs, preserved at the available source resolution. They are evidence of printed marks, not reconstructed vector logos. The sample documents design usage from 1995 to 2009; it does not establish an exclusive sequence or exact redesign dates.</p></section>'
    shell('/history/brand-identity/','Kings of Kings Logos & Banners | Visual Brand History','Explore the original Kings of Kings crown, International lions crest, logo variants and colourful banners preserved from the record, concert and website archives.',identity)
    privacy=intro('PRIVACY & COOKIES','Your visit.<br><em>Your privacy.</em>','Information about the current Kings of Kings website preview.')+'<section class="section reading"><h2>Cookies and tracking</h2><p>This rebuilt preview does not load analytics, advertising trackers, social-media embeds or third-party fonts. It does not set analytics or advertising cookies. Images and fonts are served with the website.</p><h2>Your notice preference</h2><p>If you accept the privacy notice, this website stores that acknowledgement in your browser’s local storage under kok_privacy_notice. This is a preference on your device, not an advertising profile. You can clear it through your browser’s site-data controls.</p><h2>Links and email</h2><p>External links, including social networks and release references, open services with their own privacy policies. Email links open your email application; the preview does not send or store form submissions. Forms are being prepared for launch.</p><h2>Before public launch</h2><p>This notice describes the local preview. Hosting logs, any future ticketing, mailing-list, analytics or account services, retention periods and the responsible contact details must be reflected here when those services are selected.</p><p>Use the appropriate <a href="/contact/">contact form</a> for your enquiry. Enquiry details will be used to respond; mailing updates require a separate opt-in.</p></section>'
    shell('/privacy/','Privacy & Cookies','Privacy and cookie information for the Kings of Kings International website preview, including browser preferences and external links.',privacy)
    # Event page uses one content collection for all future KOKI updates.
    today=datetime.date.today().isoformat()
    past=[e for e in events if e.get('status')=='past' or (e.get('date') and e['date']<today)]
    upcoming=[e for e in events if e not in past and e.get('status')=='upcoming']
    upcards='<div class="event-grid">'+''.join(card(e).replace('PAST EVENT','UPCOMING EVENT') for e in upcoming)+'</div>' if upcoming else '<div class="announcement"><span class="status-dot"></span><div><strong>New dates will appear here once confirmed.</strong><p>Contact the events team for upcoming show announcements and official ticket information.</p></div><a class="text-link" href="mailto:events@kingsofkingsinternational.com">Ask about shows ↗</a></div>'
    cities=sorted(set(e['city'].split(',')[0] for e in past))
    eventbody=intro('LIVE MUSIC / SHARED EXPERIENCES','The music.<br><em>The moments.</em>','Find upcoming Kings of Kings events and explore the live archive.')+'<nav class="event-jumps" aria-label="Event sections"><a href="#upcoming">Upcoming events ↓</a><a href="#history">Past events ↓</a><a href="/history/">Archive stories ↗</a></nav><section class="section" id="upcoming"><p class="eyebrow">WHAT’S NEXT</p><h2>Upcoming <em>events.</em></h2>'+upcards+'</section><section class="section" id="history"><p class="eyebrow">THE LIVE ARCHIVE</p><h2>Past <em>events.</em></h2><div class="filter-row" role="group" aria-label="Filter events by city"><button class="filter active" data-filter="all" aria-pressed="true">All cities</button>'+''.join(f'<button class="filter" data-filter="{esc(c)}" aria-pressed="false">{esc(c)}</button>' for c in cities)+'</div><div class="event-grid filter-grid">'+''.join(f'<div data-city="{esc(e["city"].split(",")[0])}">{card(e)}</div>' for e in past)+'</div><p class="small-note">Original posters are preserved as historical documents. Ticket prices and offers on past-event artwork have expired.</p><a class="text-link" href="/history/">Discover more archive stories ↗</a><br><a class="text-link" href="/history/site-event-collection/">More original event posters & campaigns →</a></section>'
    eventbody=eventbody.replace('<section class="section" id="history">',recent_feature+'<section class="section archive-tiles" id="history">')
    shell('/studio/','Reggae Events | Upcoming Shows & Event History','Find upcoming Kings of Kings International shows and explore past concerts, Toronto and Montréal showcases, original flyers and artist lineups.',eventbody)
    artistbody=intro('ON RECORD / ON STAGE','Artists in<br><em>the Kings archive.</em>','Follow the names through documented recording credits and original concert artwork.')
    artistbody+='<section class="section"><p class="eyebrow">ON RECORD / RELEASE CREDITS</p><div class="artist-name-grid">'+''.join('<a href="/record-label/?artist='+__import__('urllib.parse',fromlist=['quote']).quote(a)+'#catalogue">'+esc(a)+' <span aria-hidden="true">↗</span></a>' for a in artists)+'</div></section>'
    artistbody+='<section class="section"><p class="eyebrow">ON STAGE / THE ORIGINAL SHOW FLYERS</p><h2>Shared stages.<br><em>Distinct stories.</em></h2><p>Concert appearances are documented on the original flyers. Explore each show for its performers and artwork.</p><div class="event-grid">'+''.join(card(e) for e in events[-3:])+'</div><a class="text-link" href="/history/">More archive stories ↗</a></section>'
    shell('/artists/','Artists in the Kings Archive | Recording Credits & Live Shows','Explore Kings of Kings artist release credits and historic concert appearances, with source-linked records and original show flyers.',artistbody)
    # Artist pages distinguish recording material from event appearances.
    colin=intro('RECORDING ARTIST / THE KINGS ARCHIVE','Colin Levy.<br><em>Iley Dread.</em>','Discover original record artwork and live-show campaigns spanning Colin Levy, Iley Dread and Iley Chardavid.')+f'<section class="section label-story"><div>{img("lovers-holiday-ad","Colin Levy original Lover’s Holiday campaign portrait")}</div><div><p class="eyebrow">RECORDS & LIVE SHOWCASES</p><h2>Follow<br><em>the music.</em></h2><p>The record sleeves and campaign artwork connect the artist’s names across Lover’s Holiday, Unleashed and Unite the People. The 2016 flyers document live record-release showcases in Montréal and Toronto.</p><a class="button gold" href="/record-label/">Explore the label ↗</a></div></section><section class="section"><div class="sleeve-grid">'+''.join(releasecard(r) for r in features if r['id']!='miracle')+'</div></section>'
    shell('/artists/colin-levy/','Colin Levy / Iley Dread | Records & Live Archive','Explore Colin Levy, Iley Dread and Iley Chardavid through original Kings release artwork, Lover’s Holiday, Unleashed and concert-showcase history.',colin)
    gallery=intro('THE ORIGINAL ARTWORK','Music you can<br><em>see.</em>','Record sleeves, release campaigns and concert posters from the Kings archive. Open any artwork to inspect the original composition.')+'<section class="section gallery-grid">'
    artlist=[('unite-the-people','Unite the People remastered cover'),('miracle','Miracle — Judy Mowatt feat. Chardavid'),('lovers-holiday','Lover’s Holiday cover'),('toronto-2016','Toronto Unleashed showcase, May 1, 2016'),('montreal-2016','Montréal Unleashed showcase, April 30, 2016'),('cocoa-tea-2018','1000 Degrees of Sweet, October 7, 2018'),('capleton-archive','Capleton with Cocoa Tea at B.B. King Blues Club'),('unleashed-2016','Iley Chardavid Unleashed campaign'),('western-consciousness-2011','Western Consciousness April 30, 2011 poster'),('release-showcase-2010','Lover’s Holiday release showcase'),('miracle-jamaica-day','Miracle Jamaica Day flyer'),('unleashed-press','Unleashed magazine campaign')]
    flyer_links={r['image']:'/history/flyers/'+r['id']+'/' for r in data('flyers.json')}
    for name,alt in artlist:
        src='/assets/archive/'+name+'.webp'
        if src in flyer_links:gallery+=f'<a class="gallery-item" href="{flyer_links[src]}" aria-label="Explore {esc(alt)}">{img(name,alt)}<span aria-hidden="true">↗</span></a>'
        else:gallery+=f'<button class="gallery-item" data-image="{src}" data-alt="{esc(alt)}" aria-label="Enlarge {esc(alt)}">{img(name,alt)}<span aria-hidden="true">↗</span></button>'

    shell('/gallery/','Kings Artwork Gallery | Record Covers & Historic Flyers','Browse original Kings of Kings record covers, Colin Levy and Judy Mowatt artwork, historic concert posters and Unleashed showcase flyers.',gallery+'</section>')
